import os
from pathlib import Path
from typing import Dict, Optional

def inspect_smbios_dmi_tables(sysfs_root: str = "/sys/class/dmi/id") -> Dict[str, Optional[str]]:
    """Reads SMBIOS hardware information strictly through Linux read-only sysfs."""
    root = Path(sysfs_root)
    dmi_fields = {
        "bios_vendor": "bios_vendor",
        "bios_version": "bios_version",
        "bios_date": "bios_date",
        "board_vendor": "board_vendor",
        "board_name": "board_name",
        "product_uuid": "product_uuid",
        "sys_vendor": "sys_vendor",
    }
    results = {}
    for key, filename in dmi_fields.items():
        node = root / filename
        if node.exists() and os.access(node, os.R_OK):
            try:
                results[key] = node.read_text(encoding="utf-8").strip()
            except OSError:
                results[key] = None
        else:
            results[key] = None
    return results

if __name__ == "__main__":
    info = inspect_smbios_dmi_tables()
    print(f"SMBIOS BIOS Version: {info.get('bios_version', 'UNKNOWN')}")

