import re
from typing import Dict, List, Any, Tuple

def parse_efibootmgr_verbose(output: str) -> Dict[str, Any]:
    """Parses efibootmgr verbose output strictly in read-only inspection mode."""
    boot_order = []
    boot_current = None
    entries: Dict[str, Dict[str, str]] = {}

    for line in output.splitlines():
        line = line.strip()
        if line.startswith("BootCurrent:"):
            boot_current = line.split(":", 1)[1].strip()
        elif line.startswith("BootOrder:"):
            raw_order = line.split(":", 1)[1].strip()
            boot_order = [item.strip() for item in raw_order.split(",") if item.strip()]
        elif re.match(r"^Boot[0-9A-Fa-f]{4}\*?", line):
            m = re.match(r"^Boot([0-9A-Fa-f]{4})(\*)?\s+(.*?)\t(.*)$", line)
            if m:
                entry_id, active, title, devpath = m.groups()
                entries[entry_id] = {
                    "active": bool(active),
                    "title": title.strip(),
                    "device_path": devpath.strip(),
                }

    return {
        "boot_current": boot_current,
        "boot_order": boot_order,
        "entries": entries,
    }

