@layer reset, base, layout, components, utilities;

@layer reset {
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }
}

@layer base {
  body {
    font-family: system-ui, -apple-system, sans-serif;
    color: #1a1a1a;
    background-color: #fafafa;
  }
}

@layer components {
  /* :where() gives 0-0-0 specificity: highly overridable defaults */
  :where(.btn, .card, .badge) {
    border-radius: 0.375rem;
    transition: background-color 150ms ease;
  }
  /* :is() takes the specificity of its most specific argument */
  :is(header, footer, main) > .content-wrapper {
    max-width: 1200px;
    margin-inline: auto;
  }
  .btn {
    display: inline-flex;
    padding: 0.5rem 1rem;
    background: #2563eb;
    color: #fff;
  }
}

@layer utilities {
  .u-hidden {
    display: none;
  }
}

