export type Primitive = string | number | boolean | bigint | symbol | null | undefined;

export type DeepReadonly<T> = T extends Primitive
  ? T
  : T extends (...args: readonly any[]) => any
  ? T
  : { readonly [K in keyof T]: DeepReadonly<T[K]> };

export function getNestedProperty<
  TObject extends Record<string, any>,
  TKey extends keyof TObject
>(target: TObject, key: TKey): TObject[TKey] {
  return target[key];
}

export function createRecordMap<
  const TKeys extends readonly string[],
  TValue
>(keys: TKeys, initialValue: TValue): Record<TKeys[number], TValue> {
  const result = {} as Record<TKeys[number], TValue>;
  for (const key of keys) {
    result[key as TKeys[number]] = initialValue;
  }
  return result;
}

export function mergeEntities<
  TBase extends { readonly id: string | number },
  TExtension extends Record<string, unknown>
>(base: TBase, extension: TExtension): TBase & TExtension {
  return Object.assign({}, base, extension);
}

