export interface AgentConfig {
  readonly seatId: number;
  readonly model: string;
  readonly vramLimitMb: number;
  readonly roles: readonly ('compiler' | 'systems' | 'web' | 'lora')[];
}

export const SEAT_SETTINGS = {
  seatId: 3,
  model: 'qwen3.5-9b-abli',
  vramLimitMb: 7372,
  roles: ['compiler', 'lora'] as const,
} satisfies AgentConfig;

export type MeshEvent =
  | { kind: 'HEARTBEAT'; seat: number; timestamp: string }
  | { kind: 'CLAIM'; seat: number; path: string; intent: string }
  | { kind: 'RELEASE'; seat: number; path: string };

export function formatEvent(event: MeshEvent): string {
  switch (event.kind) {
    case 'HEARTBEAT': return `[HB] Seat ${event.seat}`;
    case 'CLAIM':     return `[LOCK] Seat ${event.seat} -> ${event.path}`;
    case 'RELEASE':   return `[FREE] Seat ${event.seat} -> ${event.path}`;
    default: {
      const _exhaustive: never = event;
      throw new Error(`Unhandled event: ${_exhaustive}`);
    }
  }
}

