#include <assert.h>

typedef struct {
    int items[16];
    size_t count;
} fixed_stack_t;

void stack_init(fixed_stack_t *s) {
    s->count = 0;
}

bool stack_push(fixed_stack_t *s, int val) {
    if (!s || s->count >= 16) return false;
    s->items[s->count++] = val;
    return true;
}

bool stack_pop(fixed_stack_t *s, int *out) {
    if (!s || !out || s->count == 0) return false; // Bounds check
    s->count--;
    *out = s->items[s->count];
    return true;
}

